  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'قم بإعداد CuaDriver على مضيف وقت التشغيل هذا. يمتلك CuaDriver أذونات نظام التشغيل؛ يقوم Dovo بتوصيل الوكلاء من خلال MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'استضافة الأسماء أو المسارات القابلة للتنفيذ، بدون اقتباس الصدفة. تجاوزات الوكيل لها الأسبقية. تستخدم المحطات الجديدة إعدادات الصدفة هذه.',
