  'Continue interrupted turns after runtime restart':
    'متابعة المنعطفات المتقطعة بعد إعادة تشغيل وقت التشغيل',
  'Interrupted turns can resume automatically. Queued messages stay paused until you resume them. Stopped tasks and automations still require Retry.':
    'يمكن استئناف المنعطفات المتقطعة تلقائيًا. تظل الرسائل الموضوعة في قائمة الانتظار متوقفة مؤقتًا حتى تستأنفها. لا تزال المهام المتوقفة وعمليات التشغيل التلقائي تتطلب إعادة المحاولة.',
