  'After 7 days': 'بعد 7 أيام',
  'After 14 days': 'بعد 14 يوما',
  'After 30 days': 'بعد 30 يوما',
  'Computer fallback when no scoped archiving rule is set. Scoped On archives after time in Settled; scoped Off disables automatic archiving. Running, waiting, pinned tasks and open terminals are protected.':
    'احتياطي الكمبيوتر عند عدم تعيين قاعدة أرشفة محددة النطاق. تم تحديد نطاقه في الأرشيف بعد فترة من الاستقرار؛ يعمل النطاق Off على تعطيل الأرشفة التلقائية. التشغيل والانتظار والمهام المثبتة والمحطات المفتوحة محمية.',
  'Keep this computer awake while tasks run': 'أبقِ هذا الكمبيوتر مستيقظًا أثناء تشغيل المهام',
  'macOS only. Prevents idle sleep while a task is working, so it keeps going while you follow it here.':
    'ماك فقط. يمنع النوم الخامل أثناء عمل المهمة، لذلك يستمر أثناء متابعتك هنا.',
  'Model modes (experimental)': 'أوضاع النموذج (تجريبية)',
  'Tune & Maestro modes (experimental)': 'أوضاع Tune & Maestro (تجريبية)',
  'Tune chooses a model within the default agent. Maestro chooses the agent and model together. Both choose reasoning once before the first turn. Inherit keeps project defaults.':
    'يختار Tune نموذجًا ضمن الوكيل الافتراضي. يختار Maestro الوكيل والنموذج معًا. يختار كلاهما أسلوب الاستدلال مرة واحدة قبل الدور الأول. يُبقي «وراثة» الإعدادات الافتراضية للمشروع.',
