  stopped: 'متوقفة',
  'A thread can change it before its first message.': 'يمكن للمحادثة تغيير ذلك قبل رسالتها الأولى.',
  'Full network access. The agent can reach any address the host can.':
    'وصول كامل إلى الشبكة. يستطيع الوكيل الوصول إلى أي عنوان يصل إليه المضيف.',
